/**
 * Check Story Tests Passed — postJSAction for story_done_check agent.
 *
 * Runs on every SM cycle for each Story in "In Testing".
 * - If all linked Test Cases are "Passed" → moves the Story to "Done".
 * - If any linked Test Case is still in an in-flight review/automation status
 *   (In Review - Passed/Failed, In Development, etc.) → releases the lock and
 *   waits for the review/merge/automation agents to finish.
 * - If any linked Test Case is "Failed" and has no linked non-Done bug → waits
 *   for bulk_bugs_creation to create/link the bug.
 * - If any linked Test Case has a linked non-Done bug → moves the Story to
 *   "Bug To Fix" so the bug-fix pipeline can run.
 * - Otherwise all non-passed Test Cases are ready for re-test (bugs Done or no
 *   bugs) → moves the Story back to "Ready For Testing" to trigger a re-run.
 *
 * gh-1080 CRAP split: parameter parsing, TC classification and the
 * outcome dispatch are small top-level helpers; action() only orchestrates.
 * Tracker/post calls and their order are byte-identical to the pre-split flow.
 */

const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const trackersModule = require('./common/trackers.js');
const linkedIssuesReport = require('./common/linkedIssuesReport.js');

// ── gh-1080: pure parse helpers ──────────────────────────────────────────────

function parseCheckParams(params) {
    var customParams = params.jobParams && params.jobParams.customParams;
    return {
        ticketKey: params.ticket && params.ticket.key,
        customParams: customParams,
        removeLabel: customParams && customParams.removeLabel
    };
}

function resolveCustomStatuses(jiraConfig, customParams) {
    // Legacy override channel: customParams.customStatuses still wins over .dmtools/config.js statuses
    return Object.assign({}, jiraConfig.statuses, (customParams && customParams.customStatuses) || {});
}

function buildCheckContext(params) {
    var parsed = parseCheckParams(params);
    var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    var jiraConfig = projectConfig.jira;
    return {
        ticketKey: parsed.ticketKey,
        customParams: parsed.customParams,
        removeLabel: parsed.removeLabel,
        tracker: trackersModule.createTracker(projectConfig, parsed.customParams || {}),
        statuses: resolveCustomStatuses(jiraConfig, parsed.customParams),
        testCaseType: jiraConfig.issueTypes.TEST_CASE || 'Test Case',
        bugType: jiraConfig.issueTypes.BUG || 'Bug'
    };
}

// ── gh-1080: pure classify helpers (tracker access is injected via `gate`) ───

function isFinalStage(tc, gate) {
    return gate.hasStage(tc, 'PASSED', gate.statuses.PASSED) ||
        gate.hasStage(tc, 'SKIPPED', gate.statuses.SKIPPED) ||
        gate.hasStage(tc, 'IRRELEVANT', gate.statuses.IRRELEVANT);
}

/**
 * Drops one Test Case into exactly one bucket:
 * inFlight (review/automation still running), pendingBug (open linked bug),
 * waitingForBugs (Failed, no bug yet) or readyForRetest (everything else).
 */
function classifyTestCase(tc, gate, buckets) {
    if (isFinalStage(tc, gate)) return;

    if (gate.inFlight(tc)) {
        buckets.inFlight.push(tc.key);
        return;
    }

    var pendingBugKey = gate.pendingBugKey(tc.key);
    if (pendingBugKey) {
        buckets.pendingBug.push({ key: tc.key, status: gate.statusOf(tc), bugKey: pendingBugKey });
        return;
    }

    if (gate.hasStage(tc, 'FAILED', gate.statuses.FAILED)) {
        buckets.waitingForBugs.push(tc.key);
    } else {
        buckets.readyForRetest.push(tc.key);
    }
}

function bucketTestCases(allTCs, gate) {
    var buckets = { inFlight: [], pendingBug: [], waitingForBugs: [], readyForRetest: [] };
    allTCs.forEach(function(tc) {
        classifyTestCase(tc, gate, buckets);
    });
    return buckets;
}

function allTestsConcluded(buckets) {
    return buckets.inFlight.length === 0 &&
        buckets.pendingBug.length === 0 &&
        buckets.waitingForBugs.length === 0 &&
        buckets.readyForRetest.length === 0;
}

function action(params) {
    const ctx = buildCheckContext(params);
    const tracker = ctx.tracker;
    const ticketKey = ctx.ticketKey;

    function releaseLock() {
        if (ticketKey && ctx.removeLabel) {
            try {
                tracker.removeLabel(ticketKey, ctx.removeLabel);
                console.log('Released SM label — will re-check next cycle');
            } catch (e) {
                console.warn('Failed to remove SM label:', e);
            }
        }
    }

    function postTokenUsageSafely() {
        tokenUsageComment.postTokenUsageSafely(ticketKey, params);
    }

    function findLinkedTCs() {
        try {
            // JQL text: provider-specific query (WIQL on ado)
            // gh-916: in label mode the stage gates also read markers, so labels are requested;
            // 'none' mode sends the exact same fields list as before.
            var fields = ['key', 'status'];
            if (tracker.stageFallback() === 'label') fields = fields.concat(['labels']);
            return tracker.searchIssues(linkedIssuesReport.buildLinkedIssuesQuery(tracker.provider(), ticketKey, 'issuetype = "' + ctx.testCaseType + '"', { issueType: ctx.testCaseType }), {
                fields: fields,
                maxResults: 100
            }) || [];
        } catch (e) {
            console.warn('Failed to fetch linked Test Cases:', e);
            return [];
        }
    }

    function findLinkedBugs(tcKey) {
        try {
            // JQL text: provider-specific query (WIQL on ado)
            return tracker.searchIssues(linkedIssuesReport.buildLinkedIssuesQuery(tracker.provider(), tcKey, 'issuetype = "' + ctx.bugType + '"', { issueType: ctx.bugType }), {
                fields: ['key', 'status'],
                maxResults: 50
            }) || [];
        } catch (e) {
            console.warn('Failed to fetch linked bugs for', tcKey, e);
            return [];
        }
    }

    function findPendingBugKey(tcKey) {
        var bugs = findLinkedBugs(tcKey);
        for (var i = 0; i < bugs.length; i++) {
            var status = bugs[i].fields && bugs[i].fields.status && bugs[i].fields.status.name;
            if (status !== ctx.statuses.DONE) {
                return bugs[i].key;
            }
        }
        return null;
    }

    // gh-916: stage gates go through tracker.hasStage — a TC marked stage_<key> by a rejected
    // transition counts as being in the stage when jira.stageFallback is 'label'; in the default
    // 'none' mode hasStage compares the status only (the exact previous behaviour).
    function isInFlightStatus(tc) {
        var status = tcStatus(tc);
        return tracker.hasStage(tc, 'IN_REVIEW_PASSED', ctx.statuses.IN_REVIEW_PASSED) ||
            tracker.hasStage(tc, 'IN_REVIEW_FAILED', ctx.statuses.IN_REVIEW_FAILED) ||
            status === ctx.statuses.IN_DEVELOPMENT ||
            status === ctx.statuses.READY_FOR_DEVELOPMENT;
    }

    function tcStatus(tc) {
        return tc && tc.fields && tc.fields.status && tc.fields.status.name;
    }

    function classificationGate() {
        return {
            statuses: ctx.statuses,
            hasStage: function(tc, stageKey, statusName) { return tracker.hasStage(tc, stageKey, statusName); },
            statusOf: tcStatus,
            inFlight: isInFlightStatus,
            pendingBugKey: findPendingBugKey
        };
    }

    // ── gh-1080: outcome steps (extracted verbatim from the pre-split flow) ──

    function completeAllPassed(totalTCs) {
        console.log('All', totalTCs, 'Test Case(s) passed — moving', ticketKey, 'to Done');

        tracker.moveToStatus(ticketKey, ctx.statuses.DONE);

        tracker.postComment(ticketKey, 'h3. ✅ Story Complete — All Test Cases Passed\n\n' +
                'All *' + totalTCs + '* linked Test Case(s) are in *Passed* status.\n\n' +
                'The story has been automatically moved to *Done*.');

        console.log('✅ Story', ticketKey, 'moved to Done');

        postTokenUsageSafely();

        return { success: true, action: 'moved_to_done', totalTCs: totalTCs, ticketKey: ticketKey };
    }

    // Step 3: Some TCs have open bugs → Story must wait in Bug To Fix
    function moveStoryToBugToFix(pendingBugTCs) {
        var bugList = pendingBugTCs.map(function(item) {
            return '*' + item.bugKey + '* (from ' + item.key + ')';
        }).join('\n');

        console.log('Found', pendingBugTCs.length, 'TC(s) with pending bugs — moving Story to Bug To Fix');

        // gh-916: BUG_TO_FIX can be tag-only (restricted ADO workflows) — stage-label fallback.
        var bugToFixMove = tracker.moveToStatusOrMark(ticketKey, ctx.statuses.BUG_TO_FIX, 'BUG_TO_FIX');
        if (bugToFixMove.moved || bugToFixMove.marked) {
            tracker.postComment(ticketKey, 'h3. 🐛 Story Moved to Bug To Fix\n\n' +
                    'The following linked Test Cases have open bugs:\n\n' + bugList + '\n\n' +
                    'The Story has been moved to *Bug To Fix*. It will return to *Ready For Testing* once all linked bugs are *Done*.');

            console.log('✅ Story', ticketKey, 'moved to Bug To Fix');
        }
        releaseLock();

        postTokenUsageSafely();

        return { success: true, action: 'moved_to_bug_to_fix', pendingBugTCs: pendingBugTCs.length, ticketKey: ticketKey };
    }

    // Step 5: All remaining non-passed TCs are ready for re-test → back to Ready For Testing
    function moveStoryToReadyForTesting(readyForRetestCount) {
        console.log('All non-passed TCs are ready for re-test — moving Story to Ready For Testing');

        // gh-916: READY_FOR_TESTING can be tag-only (restricted ADO workflows) — stage-label fallback.
        var retestMove = tracker.moveToStatusOrMark(ticketKey, ctx.statuses.READY_FOR_TESTING, 'READY_FOR_TESTING');
        if (retestMove.moved || retestMove.marked) {
            tracker.postComment(ticketKey, 'h3. 🔄 Story Ready for Re-test\n\n' +
                    'All linked bugs are resolved. The Story has been moved back to *Ready For Testing* to re-run the linked Test Cases.');

            console.log('✅ Story', ticketKey, 'moved to Ready For Testing');
        }
        releaseLock();

        postTokenUsageSafely();

        return { success: true, action: 'moved_to_ready_for_testing', readyForRetestTCs: readyForRetestCount, ticketKey: ticketKey };
    }

    function applyCheckOutcome(buckets, totalTCs) {
        if (allTestsConcluded(buckets)) {
            return completeAllPassed(totalTCs);
        }

        // Step 2: Some TCs are still being reviewed/developed — wait for those agents
        if (buckets.inFlight.length > 0) {
            console.log(buckets.inFlight.length, 'TC(s) still in review/automation — releasing lock, will re-check next cycle');
            releaseLock();
            return { success: true, action: 'waiting_in_flight', totalTCs: totalTCs, inFlightTCs: buckets.inFlight, ticketKey: ticketKey };
        }

        if (buckets.pendingBug.length > 0) {
            return moveStoryToBugToFix(buckets.pendingBug);
        }

        // Step 4: Some Failed TCs still have no linked bug — wait for bulk_bugs_creation
        if (buckets.waitingForBugs.length > 0) {
            console.log('Failed TCs without linked bugs — releasing lock, will re-check next cycle');
            releaseLock();
            return { success: true, action: 'waiting_for_bugs', totalTCs: totalTCs, waitingForBugsTCs: buckets.waitingForBugs, ticketKey: ticketKey };
        }

        return moveStoryToReadyForTesting(buckets.readyForRetest.length);
    }

    try {
        if (!ticketKey) throw new Error('params.ticket.key is missing');
        console.log('=== Story done check for', ticketKey, '===');

        const allTCs = findLinkedTCs();
        const totalTCs = allTCs.length;
        console.log('Linked Test Cases:', totalTCs);

        if (totalTCs === 0) {
            console.log('No linked Test Cases found — releasing lock, will re-check next cycle');
            releaseLock();
            return { success: true, action: 'no_test_cases', ticketKey: ticketKey };
        }

        const buckets = bucketTestCases(allTCs, classificationGate());
        return applyCheckOutcome(buckets, totalTCs);

    } catch (error) {
        console.error('❌ Error in checkStoryTestsPassed:', error);
        releaseLock();
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Check Bug Tests Passed — postJSAction for bug_done_check agent.
 *
 * Runs on every SM cycle for each Bug in "In Testing".
 * - Looks at *directly* linked Test Cases first (avoids blocking a bug on
 *   unrelated Test Cases that happen to be connected through a parent Story
 *   or other transitive links).
 * - A Test Case in "Bug To Fix" is treated as non-blocking when it already
 *   has at least one linked Bug other than the current Bug. That bug will be
 *   handled by the bug-fix pipeline, and the current Bug must not deadlock
 *   waiting for it.
 * - Skipped and Irrelevant Test Cases are also non-blocking.
 * - If there are no direct Test Case links → falls back to the broad
 *   linkedIssues query for backward compatibility.
 * - Otherwise → removes the SM idempotency label so the SM re-triggers
 *   this check on the next cycle.
 */

const { LABELS } = require('./config.js');
const configLoader = require('./configLoader.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const scmModule = require('./common/scm.js');
const trackersModule = require('./common/trackers.js');
const checkHelpers = require('./checkBugTestsPassedHelpers.js');
const linkedIssuesReport = require('./common/linkedIssuesReport.js');
const smLock = require('./common/smLock.js');

/**
 * Helper: remove SM label so the check re-runs on the next SM cycle.
 * gh-1188: extracted from the action closure — a removal failure is
 * swallowed (non-fatal, as before).
 * gh-1250: shared implementation in common/smLock.js.
 */
function releaseLock(tracker, ticketKey, removeLabel) {
    smLock.releaseLock(tracker, ticketKey, removeLabel);
}

function getTicketSafely(tracker, ticketKey) {
    try {
        return tracker.getIssue(ticketKey) || {};
    } catch (e) {
        console.warn('Failed to read ticket', ticketKey, ':', e);
        return {};
    }
}

/**
 * gh-1188: one issuelink entry → linked Test Case stub (or null) — pure.
 */
function directLinkedTcOf(link, testCaseType) {
    var other = link.outwardIssue || link.inwardIssue;
    if (!other || !other.fields || !other.fields.issuetype) return null;
    if (other.fields.issuetype.name === testCaseType) {
        return other;
    }
    return null;
}

/**
 * gh-1188: the issuelinks → Test Case stub collection — pure.
 */
function collectDirectTcLinks(ticket, testCaseType) {
    const issueLinks = ticket && ticket.fields && ticket.fields.issuelinks;
    if (!Array.isArray(issueLinks) || issueLinks.length === 0) {
        return [];
    }
    const tcs = [];
    issueLinks.forEach(function(link) {
        var tc = directLinkedTcOf(link, testCaseType);
        if (tc) tcs.push(tc);
    });
    return tcs;
}

/**
 * gh-1188: gh-916 review — Jira returns issuelinks stubs with a reduced field set (summary/status/
 * issuetype — never labels), so in 'label' mode hasStage could not recognise a stage_<key>
 * marker on the preferred path and a marked TC blocked the Bug forever. Re-fetch each
 * TC in full so labels are real; the 'none' default keeps the stubs — status-only comparison,
 * no extra reads, the exact previous behaviour.
 */
function refetchTcsWithLabels(tcs, tracker) {
    if (tracker.stageFallback() === 'label' && tcs.length > 0) {
        return tcs.map(function(tc) {
            try {
                return tracker.getIssue(tc.key) || tc;
            } catch (e) {
                console.warn('Could not re-fetch', tc.key, 'with full fields — falling back to the link stub:', e);
                return tc;
            }
        });
    }
    return tcs;
}

function directLinkedTestCases(ticket, ticketKey, testCaseType, tracker) {
    try {
        return refetchTcsWithLabels(collectDirectTcLinks(ticket, testCaseType), tracker);
    } catch (e) {
        console.warn('Failed to read direct issue links for', ticketKey, ':', e);
        return [];
    }
}

function allLinkedTestCases(tracker, provider, ticketKey, testCaseType) {
    try {
        // JQL text: provider-specific query (WIQL on ado)
        return tracker.searchIssues(linkedIssuesReport.buildLinkedIssuesQuery(provider, ticketKey, 'issuetype = "' + testCaseType + '"', { issueType: testCaseType }), {
            maxResults: 100
        }) || [];
    } catch (e) {
        console.warn('Failed to fetch linked Test Cases via JQL:', e);
        return [];
    }
}

function linkedBugsOf(tracker, provider, tcKey, bugType) {
    try {
        // JQL text: provider-specific query (WIQL on ado)
        return tracker.searchIssues(linkedIssuesReport.buildLinkedIssuesQuery(provider, tcKey, 'issuetype = "' + bugType + '"', { issueType: bugType }), {
            maxResults: 50
        }) || [];
    } catch (e) {
        console.warn('Failed to fetch linked Bugs for', tcKey, ':', e);
        return [];
    }
}

function isBlockingTestCase(tracker, tc, ticketKey, bugType, provider, jiraConfig) {
    // gh-916: stage gates go through tracker.hasStage — a TC marked stage_<key> by a rejected
    // transition counts as being in the stage when jira.stageFallback is 'label'; in the default
    // 'none' mode hasStage compares the status only (the exact previous behaviour).
    var status = tc.fields && tc.fields.status && tc.fields.status.name;

    // Passed / intentionally skipped / no longer applicable are always non-blocking.
    if (tracker.hasStage(tc, 'PASSED', jiraConfig.statuses.PASSED) ||
        tracker.hasStage(tc, 'SKIPPED', jiraConfig.statuses.SKIPPED) ||
        tracker.hasStage(tc, 'IRRELEVANT', jiraConfig.statuses.IRRELEVANT)) {
        return false;
    }

    // A TC that is already tracked as "Bug To Fix" is non-blocking when it
    // has its own linked Bug(s) other than the current Bug. Those Bugs will
    // be fixed through the normal bug-fix pipeline; waiting for them here
    // creates deadlocks (e.g. TS-1356 was stuck because parent-Story
    // regression TCs TS-501/TS-252 were Bug To Fix). We count *any* other
    // linked Bug (even Done) so stale TCs that were already addressed do not
    // hold the current Bug hostage.
    if (tracker.hasStage(tc, 'BUG_TO_FIX', jiraConfig.statuses.BUG_TO_FIX)) {
        var linkedBugs = linkedBugsOf(tracker, provider, tc.key, bugType);
        // gh-1043: pure predicate extracted (and unit-tested) in checkHelpers.
        if (checkHelpers.decideOtherActiveBug(linkedBugs, ticketKey, jiraConfig.statuses.DONE)) {
            console.log('TC', tc.key, 'is Bug To Fix but already tracked by another active Bug — treating as non-blocking');
            return false;
        }
    }

    return true;
}

/**
 * gh-1188: the open test-automation PR probe — a scm failure degrades to
 * "no PR found" (as before), never a throw.
 */
function findOpenTestPrForTicket(scmFactory, projectConfig, ticketKey) {
    try {
        var scm = scmFactory.createScm(projectConfig);
        var prList = scm.listPrs('open') || [];
        // gh-1043: pure filter extracted (and unit-tested) in checkHelpers.
        return checkHelpers.findOpenTestPr(prList, ticketKey);
    } catch (e) {
        console.warn('Could not list open PRs for', ticketKey, ':', e);
        return null;
    }
}

/**
 * gh-1188: the blocking-TC route resolution — if the test-automation PR has
 * already been merged and finalized, any still-blocking Test Case means the
 * fix did not work: route the Bug to In Rework (once) or Blocked (after a
 * rework attempt) instead of waiting forever.
 *
 * Anti-cycle guard (gh-1043: pure route decision in checkHelpers): do not
 * bounce a finalized Bug back to In Rework more than once for the same
 * blockers. After one rework attempt, move to Blocked so a human triages
 * persistent blockers instead of burning CI minutes in an infinite loop.
 */
function resolveBlockingRoute(tracker, ticketKey, labels, totalTCs, blockingTCs, jiraConfig, removeLabel) {
    const blockingCount = blockingTCs.length;
    var route = checkHelpers.decidePostFixRoute(labels, LABELS.TEST_PR_FINALIZED);
    if (route === 'blocked') {
        console.log('Test PR finalized and one rework already attempted — moving', ticketKey, 'to Blocked for triage');
        tracker.moveToStatus(ticketKey, jiraConfig.statuses.BLOCKED);
        tracker.postComment(ticketKey, checkHelpers.buildBlockedAfterReworkComment(blockingTCs));
        releaseLock(tracker, ticketKey, removeLabel);
        return { success: true, action: 'moved_to_blocked', totalTCs: totalTCs, blockingCount: blockingCount, blockingTCs: blockingTCs.map(function(tc) { return tc.key; }), ticketKey: ticketKey };
    }

    if (route === 'rework') {
        console.log('Test PR finalized but', blockingCount, 'linked Test Case(s) still block — moving', ticketKey, 'to In Rework (one attempt)');
        tracker.moveToStatus(ticketKey, jiraConfig.statuses.IN_REWORK);
        tracker.addLabel(ticketKey, 'sm_bug_rework_attempted');
        tracker.postComment(ticketKey, checkHelpers.buildReworkComment(blockingTCs));
        releaseLock(tracker, ticketKey, removeLabel);
        return { success: true, action: 'moved_to_rework', totalTCs: totalTCs, blockingCount: blockingCount, blockingTCs: blockingTCs.map(function(tc) { return tc.key; }), ticketKey: ticketKey };
    }

    console.log('Not all Test Cases passed — releasing lock, will re-check next cycle');
    releaseLock(tracker, ticketKey, removeLabel);
    return { success: true, action: 'waiting', totalTCs: totalTCs, blockingCount: blockingCount, blockingTCs: blockingTCs.map(function(tc) { return tc.key; }), ticketKey: ticketKey };
}

/**
 * gh-1188: pure input resolution extracted from action.
 */
function resolveTicketKey(params) {
    return params.ticket && params.ticket.key;
}

function resolveSmLabelOptions(params) {
    var customParams = params.jobParams && params.jobParams.customParams;
    return { customParams: customParams, removeLabel: customParams && customParams.removeLabel };
}

function resolveTrackedIssueTypes(jiraConfig) {
    return {
        testCaseType: jiraConfig.issueTypes.TEST_CASE || 'Test Case',
        bugType: jiraConfig.issueTypes.BUG || 'Bug'
    };
}

function resolveTicketLabels(ticket) {
    return (ticket && ticket.fields && ticket.fields.labels) || [];
}

function filterBlockingTestCases(allTCs, tracker, ticketKey, bugType, provider, jiraConfig) {
    return allTCs.filter(function(tc) {
        return isBlockingTestCase(tracker, tc, ticketKey, bugType, provider, jiraConfig);
    });
}

/**
 * gh-1188: the open-test-automation-PR wait branch — returns the wait
 * outcome, or null when there is no PR and the Bug may proceed to Done.
 */
function openTestPrWaitResult(openTestPR, tracker, ticketKey, totalTCs, removeLabel) {
    if (!openTestPR) {
        return null;
    }
    console.log('Open test-automation PR found:', openTestPR.number, '— keeping', ticketKey, 'in In Testing until it is merged');
    releaseLock(tracker, ticketKey, removeLabel);
    return {
        success: true,
        action: 'waiting_for_test_pr_merge',
        reason: 'open_pr',
        prNumber: openTestPR.number,
        prUrl: openTestPR.html_url,
        totalTCs: totalTCs,
        ticketKey: ticketKey
    };
}

/**
 * gh-1188: Step 4 — the Done completion: move, anti-cycle label cleanup,
 * done comment, token usage, lock release (tracker call order preserved).
 */
function completeBugDone(tracker, ticketKey, totalTCs, jiraConfig, params, removeLabel) {
    tracker.moveToStatus(ticketKey, jiraConfig.statuses.DONE);

    // Clean up anti-cycle label on successful completion.
    try {
        tracker.removeLabel(ticketKey, 'sm_bug_rework_attempted');
    } catch (e) {
        console.warn('Could not remove sm_bug_rework_attempted label:', e);
    }

    tracker.postComment(ticketKey, checkHelpers.buildBugDoneComment(totalTCs));

    console.log('✅ Bug', ticketKey, 'moved to Done');

    // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
    // wrote outputs/*_usage.json during the agent run. gh-1250: the shared wrapper never throws —
    // a provider failure here must not fail the done check.
    tokenUsageComment.postTokenUsageCommentsSafely(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });

    releaseLock(tracker, ticketKey, removeLabel);
    return { success: true, action: 'moved_to_done', totalTCs: totalTCs, ticketKey: ticketKey };
}

/**
 * gh-1188: Step 1 — direct Test Cases first, linkedIssues query as fallback.
 * Returns { tcs, source } so the caller keeps its log line unchanged.
 */
function resolveLinkedTestCasesWithFallback(ticket, ticketKey, testCaseType, tracker, provider) {
    var direct = directLinkedTestCases(ticket, ticketKey, testCaseType, tracker);
    if (direct.length > 0) {
        return { tcs: direct, source: 'direct' };
    }
    console.log('No direct Test Case links found — falling back to linkedIssues query');
    return { tcs: allLinkedTestCases(tracker, provider, ticketKey, testCaseType), source: 'linkedIssues' };
}

function action(params) {
    const ticketKey = resolveTicketKey(params);
    const labelOptions = resolveSmLabelOptions(params);
    const removeLabel = labelOptions.removeLabel;

    // Load project config to get issue types (default: "Test Case" / "Bug")
    const projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
    const jiraConfig = projectConfig.jira;
    const tracker = trackersModule.createTracker(projectConfig, labelOptions.customParams || {});
    const provider = tracker.provider();
    const trackedTypes = resolveTrackedIssueTypes(jiraConfig);
    const testCaseType = trackedTypes.testCaseType;
    const bugType = trackedTypes.bugType;

    try {
        if (!ticketKey) throw new Error('params.ticket.key is missing');
        console.log('=== Bug done check for', ticketKey, '===');

        const ticket = getTicketSafely(tracker, ticketKey);
        const labels = resolveTicketLabels(ticket);

        // Step 1: Prefer directly linked Test Cases so a bug is only held up by
        // its own acceptance tests, not by every Test Case connected to a parent Story.
        var linked = resolveLinkedTestCasesWithFallback(ticket, ticketKey, testCaseType, tracker, provider);
        var allTCs = linked.tcs;

        const totalTCs = allTCs.length;
        console.log('Linked Test Cases (' + linked.source + '):', totalTCs);

        if (totalTCs === 0) {
            console.log('No linked Test Cases found — releasing lock, will re-check next cycle');
            releaseLock(tracker, ticketKey, removeLabel);
            return { success: true, action: 'no_test_cases', ticketKey: ticketKey };
        }

        // Step 2: Check whether any linked Test Case still blocks this Bug.
        const blockingTCs = filterBlockingTestCases(allTCs, tracker, ticketKey, bugType, provider, jiraConfig);
        const blockingCount = blockingTCs.length;

        console.log('Blocking Test Cases:', blockingCount, '/', totalTCs);

        if (blockingCount > 0) {
            return resolveBlockingRoute(tracker, ticketKey, labels, totalTCs, blockingTCs, jiraConfig, removeLabel);
        }

        // Step 3: All blocking Test Cases are resolved.
        // Before moving the Bug to Done, ensure there is no open test-automation
        // PR for this ticket. If there is, wait for the dedicated merge rule
        // (or the new auto-merge rule) to finalize it so it does not become an
        // orphaned open PR.
        console.log('All', totalTCs, 'linked Test Case(s) resolved — checking for open test-automation PR before Done');

        var openTestPR = findOpenTestPrForTicket(scmModule, projectConfig, ticketKey);

        var prWait = openTestPrWaitResult(openTestPR, tracker, ticketKey, totalTCs, removeLabel);
        if (prWait) {
            return prWait;
        }
        console.log('No open test-automation PR found — safe to move', ticketKey, 'to Done');

        // Step 4: Move Bug to Done
        console.log('Moving', ticketKey, 'to Done');

        return completeBugDone(tracker, ticketKey, totalTCs, jiraConfig, params, removeLabel);

    } catch (error) {
        console.error('❌ Error in checkBugTestsPassed:', error);
        releaseLock(tracker, ticketKey, removeLabel);
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action,
        // gh-1188: step helpers extracted from action — exported for direct
        // characterization tests.
        releaseLock,
        getTicketSafely,
        directLinkedTestCases,
        allLinkedTestCases,
        linkedBugsOf,
        isBlockingTestCase,
        findOpenTestPrForTicket,
        resolveBlockingRoute,
        resolveTicketKey,
        resolveSmLabelOptions,
        resolveTrackedIssueTypes,
        resolveTicketLabels,
        resolveLinkedTestCasesWithFallback,
        directLinkedTcOf,
        collectDirectTcLinks,
        filterBlockingTestCases,
        openTestPrWaitResult,
        completeBugDone
    };
}

/**
 * Pure helpers for js/checkBugTestsPassed.js (gh-1043 CRAP split).
 *
 * Every function here is side-effect free: label decisions, issue-list
 * filtering and comment string building extracted from action() so the
 * orchestration function shrinks below the CRAP threshold. Comment strings
 * must stay byte-identical to the originals — they are posted verbatim to
 * the tracker.
 */

var prLookup = require('./common/prLookup.js');

/**
 * Anti-cycle route decision once blocking Test Cases are found on a
 * finalized Bug: null (not finalized — keep waiting), 'rework' (first
 * attempt) or 'blocked' (one rework already attempted — human triage).
 */
function decidePostFixRoute(labels, finalizedLabel) {
    labels = labels || [];
    if (labels.indexOf(finalizedLabel) === -1) return null;
    return labels.indexOf('sm_bug_rework_attempted') !== -1 ? 'blocked' : 'rework';
}

/**
 * A Bug To Fix TC is non-blocking when it is already tracked by at least one
 * linked Bug other than the current one that is not Done — those Bugs go
 * through the bug-fix pipeline; waiting here would deadlock (TS-1356).
 */
function decideOtherActiveBug(linkedBugs, currentBugKey, doneStatus) {
    return (linkedBugs || []).some(function(bug) {
        var bugStatus = bug.fields && bug.fields.status && bug.fields.status.name;
        return bug.key !== currentBugKey && bugStatus !== doneStatus;
    });
}

/**
 * One '- KEY (status)' line per blocking TC, joined for the tracker comment.
 */
function buildBlockingList(blockingTCs) {
    return (blockingTCs || []).map(function(tc) {
        return '- ' + tc.key + ' (' + (tc.fields && tc.fields.status && tc.fields.status.name || 'unknown') + ')';
    }).join('\n');
}

function buildBlockedAfterReworkComment(blockingTCs) {
    return 'h3. 🚫 Test PR Finalized But Acceptance Tests Still Blocking After Rework\n\n' +
        'The test-automation PR was merged and finalized, and one rework was already attempted, but the following linked Test Case(s) are still not *Passed*:\n' +
        buildBlockingList(blockingTCs) + '\n\n' +
        'Moving the Bug to *Blocked* for manual triage instead of cycling indefinitely.';
}

function buildReworkComment(blockingTCs) {
    return 'h3. 🔄 Test PR Merged But Acceptance Tests Still Blocking\n\n' +
        'The test-automation PR was merged and finalized, but the following linked Test Case(s) are still not *Passed*:\n' +
        buildBlockingList(blockingTCs) + '\n\n' +
        'Moving the Bug to *In Rework* for one more fix attempt. If it still fails, it will be moved to *Blocked*.';
}

function buildBugDoneComment(totalTCs) {
    return 'h3. ✅ Bug Complete — All Linked Test Cases Resolved\n\n' +
        'All *' + totalTCs + '* linked Test Case(s) are either *Passed*, *Skipped*, *Irrelevant*, ' +
        'or already tracked by another Bug.\n\n' +
        'The bug has been automatically moved to *Done*.';
}

// gh-1249: the match itself lives in js/common/prLookup.js (one shared
// copy; null-safe so the scan stays total — a null entry is a non-match,
// never an abort via the action's catch).

/**
 * First open PR whose title or head branch mentions the ticket key, or null.
 * Same scan order as the original Array.find.
 */
function findOpenTestPr(prList, ticketKey) {
    var list = prList || [];
    for (var i = 0; i < list.length; i++) {
        if (prLookup.prMentionsTicket(list[i], ticketKey)) return list[i];
    }
    return null;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        decidePostFixRoute: decidePostFixRoute,
        decideOtherActiveBug: decideOtherActiveBug,
        buildBlockingList: buildBlockingList,
        buildBlockedAfterReworkComment: buildBlockedAfterReworkComment,
        buildReworkComment: buildReworkComment,
        buildBugDoneComment: buildBugDoneComment,
        prMentionsTicket: prLookup.prMentionsTicket,
        findOpenTestPr: findOpenTestPr
    };
}

