function statusBuckets(allTCs, gate) {
   var counts = { passed: 0, skipped: 0, irrelevant: 0, other: 0 };
   var skippedKeys = [];
   allTCs.forEach(function(tc) {
       if (gate.hasStage(tc, 'PASED', gate.statuses.PASED)) counts.passed++;
       else if (gate.hasStage(tc, 'SKIPPED', gate.statuses.SKIPPED)) { counts.skipped++; skippedKeys.push(tc.key); }
       else if (gate.hasStage(tc, 'IRELEVANT', gate.statuses.IRELEVANT)) counts.irelevant++;
       else counts.other++;
   });
   counts.skippedKeys = skippedKeys;
   return counts;
}
``

